package main
import("encoding/json";"fmt";"os";"math";"openalexstats/internal/eci")
func main(){var ms []struct{Year int `json:"year"`;Scheme string `json:"scheme"`;Level string `json:"level"`;Metric string `json:"metric"`;Result eci.Result `json:"result"`};b,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};if e=json.Unmarshal(b,&ms);e!=nil{panic(e)};bad:=[]any{};for _,m:=range ms{r,d,e:=eci.ReflectionsFromPrepared(m.Result,eci.ReflectionConfig{CountryIterations:20,DisciplineIterations:21});if e!=nil{panic(e)};if r.Status!="ok"{continue};for name,v:=range map[string][]float64{"country":r.ECI,"discipline":r.PCI}{mean,sq:=0.,0.;for _,x:=range v{mean+=x;sq+=x*x};mean/=float64(len(v));variance:=sq/float64(len(v));if math.Abs(mean)>1e-6||math.Abs(variance-1)>1e-8{bad=append(bad,map[string]any{"year":m.Year,"scheme":m.Scheme,"level":m.Level,"metric":m.Metric,"side":name,"mean":mean,"second_moment":variance,"country_signal_ulps":d.CountrySignalULPs,"discipline_signal_ulps":d.DisciplineSignalULPs});fmt.Println(m.Year,m.Scheme,m.Level,m.Metric,name,mean,variance)}}};p,_:=json.MarshalIndent(map[string]any{"bad":bad,"models":len(ms)},"","  ");if len(os.Args)>2{os.WriteFile(os.Args[2],append(p,'\n'),0600)}}
